function ondata(chunk) {
    for (var i = 0, len = chunk.length; i < len; ++i) {
      if (type === undefined) {

        if (++count === 5) {
          type = chunk[i];
          count = 0;
        }
      } else if (type === SIGN_RESPONSE) {

        if (!sig) {
          siglen <<= 8;
          siglen += chunk[i];
          if (++count === 4) {
            sig = Buffer.allocUnsafe(siglen);
            count = 0;
          }
        } else {
          sig[count] = chunk[i];
          if (++count === siglen) {
            sock.removeAllListeners('data');
            return sock.destroy();
          }
        }
      } else if (type === IDENTITIES_ANSWER) {

        if (keys === undefined) {
          nkeys <<= 8;
          nkeys += chunk[i];
          if (++count === 4) {
            keys = new Array(nkeys);
            count = 0;
            if (nkeys === 0) {
              sock.removeAllListeners('data');
              return sock.destroy();
            }
          }
        } else {
          if (!key) {
            keylen <<= 8;
            keylen += chunk[i];
            if (++count === 4) {
              key = Buffer.allocUnsafe(keylen);
              count = 0;
            }
          } else if (comment === false) {
            key[count] = chunk[i];
            if (++count === keylen) {
              keys[nkeys - 1] = key;
              keylen = 0;
              count = 0;
              comment = true;
              if (--nkeys === 0) {
                key = undefined;
                sock.removeAllListeners('data');
                return sock.destroy();
              }
            }
          } else if (comment === true) {
            comlen <<= 8;
            comlen += chunk[i];
            if (++count === 4) {
              count = 0;
              if (comlen > 0)
                comment = comlen;
              else {
                key = undefined;
                comment = false;
              }
              comlen = 0;
            }
          } else {

            if (++count === comment) {
              comment = false;
              count = 0;
              key = undefined;
            }
          }
        }
      } else if (type === FAILURE) {
        if (isSigning)
          error = new Error('Agent unable to sign data');
        else
          error = new Error('Unable to retrieve list of keys from agent');
        sock.removeAllListeners('data');
        return sock.destroy();
      }
    }
  }

checkprobe() {
    let that = this;
    let win = that.createWin({
      title: LANG['probedb']['title'],
      width: 350,
      height: 400,
    });
    const func_mapping = {

      'mysql_close': 'MYSQL',
      'mysqli_close': 'MYSQLI',
      'mssql_close': 'MSSQL',
      'sqlsrv_close': 'SQLSRV',
      'ora_close': 'ORACLE',
      'oci_close': 'ORACLE_OCI8',
      'ifx_close': 'INFORMIX',
      'sqlite_close': 'SQLite',
      'pg_close': 'PostgreSQL',
      'dba_close': 'DBA',
      'dbmclose': 'DBM',
      'filepro_fieldcount': 'FilePro',
      'sybase_close': 'SyBase',
    }
    let grid = win.attachGrid();
    grid.clearAll();
    grid.setHeader(`${LANG['probedb']['coltype']},${LANG['probedb']['issupport']}`);
    grid.setColTypes("ro,ro");
    grid.setColSorting('str,str');
    grid.setColumnMinWidth(100, 50);
    grid.setInitWidths("*");
    grid.setEditable(false);
    grid.init();
    win.progressOn();
    that.drive.core.request(
      that.drive.core.base.probedb()
    ).then((ret) => {
      if(ret['text'].indexOf("ERROR://") > -1){
        throw res["text"];
      }
      let _data = ret['text'].split('\n');
      let data_arr = [];
      for (let i = 0; i < _data.length; i ++) {
        let item = _data[i].split('\t');
        if(item.length<2){continue;}
        data_arr.push({
          id: i+1,
          data: [
            func_mapping.hasOwnProperty(item[0]) ? func_mapping[item[0]] : item[0],
            parseInt(item[1]) === 1 ? "√" : "×",
          ],
          style: parseInt(item[1]) === 1 ? "background-color:#ADF1B9": "",
        });
      }
      grid.parse({
        'rows': data_arr
      }, 'json');
      toastr.success(LANG['probedb']['success'], LANG_T['success']);
      win.progressOff();
    }).catch((err)=>{
      win.progressOff();
      toastr.error(JSON.stringify(err), LANG_T['error']);
    });
  }

function _showSelectDialog(title, label, options, button, callbackFcn, callbackArg, defaultValue) {
    var dialog = dialogs[title+label];
    if (dialog) {
        $("bgDialogDiv").show();
    }
    else {
        var fields = createElement("p", null, []);
	fields.appendChild(document.createTextNode(label));
        var select = createElement("select"); 
	fields.appendChild(select);
        var values = $H(options).keys();
        for (var i = 0; i < values.length; i++) {
            var option = createElement("option", null, null,
                                       { value: values[i] }, null, select);
            option.appendChild(document.createTextNode(options[values[i]]));
        }
        fields.appendChild(createElement("br"));

        fields.appendChild(createButton(null,
                                        button,
                                        callbackFcn.bind(select, callbackArg)));
	fields.appendChild(createButton(null,
                                        _("Cancel"),
                                        disposeDialog));
        dialog = createDialog(null,
                              title,
                              null,
                              fields,
                              "none");
        document.body.appendChild(dialog);
        dialogs[title+label] = dialog;
    }
    if (defaultValue)
	defaultOption = dialog.down('option[value="'+defaultValue+'"]').selected = true;
    if (Prototype.Browser.IE)
        jQuery('#bgDialogDiv').css('opacity', 0.4);
    jQuery(dialog).fadeIn('fast');
}

function addStickyControl() {
  extend(DiscussionListState.prototype, 'requestParams', function(params) {
    if (app.current.matches(IndexPage) || app.current.matches(DiscussionPage)) {
      params.include.push('firstPost');
    }
  });

  extend(DiscussionListItem.prototype, 'infoItems', function(items) {
    const discussion = this.attrs.discussion;

    if (discussion.isSticky() && !this.attrs.params.q && !discussion.lastReadPostNumber()) {
      const firstPost = discussion.firstPost();

      if (firstPost) {
        const excerpt = truncate(firstPost.contentPlain(), 175);

        items.add('excerpt', m.trust(excerpt), -100);
      }
    }
  });
}

function add_review(data, event) {
    var diag_list = [];
    for (var idx = 0; idx < data.issues().length; idx++) {
        var cur_diag = data.issues()[idx];
        if (cur_diag.selected()) {
            diag_list.push(cur_diag.jsonify());
        }
    }

    var proc_list = [];
    for (idx = 0; idx < data.procedures().length; idx++) {
        var cur_proc = data.procedures()[idx];
        if (cur_proc.selected()) {
            proc_list.push(cur_proc.jsonify());
        }
    }
    top.restoreSession();
    $.post(review_ajax, {
            pid: pid,
            encounter: enc,
            task: 'add_diags',
            diags: JSON.stringify(diag_list),
            procs: JSON.stringify(proc_list)
        },
        function (data) {
            refresh_codes();
        }

    );

    data.show(false);
}

function HueBridgeNode(config)
	{
		RED.nodes.createNode(this, config);

		var scope = this;
		let bridge = RED.nodes.getNode(config.bridge);
		let { HueBridgeMessage, HueBrightnessMessage, HueGroupMessage, HueLightMessage, HueMotionMessage, HueRulesMessage, HueSwitchMessage, HueTapMessage, HueTemperatureMessage } = require('../utils/messages');



		this.deviceUpdates = false;
		setTimeout(function(){ scope.deviceUpdates = true; }, 5000);



		this.nodeActive = true;



		this.bridgeInformation = {};



		if(bridge == null)
		{
			this.status({fill: "red", shape: "ring", text: "hue-bridge.node.not-configured"});
			return false;
		}



		this.status({fill: "grey", shape: "dot", text: "hue-bridge.node.connecting"});



		this.getBridgeInformation = function()
		{
			bridge.client.bridge.get()
			.then(bridgeInformation => {
				var hueBridge = new HueBridgeMessage(bridgeInformation, config);
				scope.send(hueBridge.msg);
				scope.status({fill: "grey", shape: "dot", text: "hue-bridge.node.connected" });


				scope.bridgeInformation = hueBridge.msg.payload;
			})
			.catch(error => {
				scope.error(error);
				if(scope.nodeActive == true)
				{
					setTimeout(function(){ scope.getBridgeInformation(); }, 3000);
				}
			});
		}



		this.getBridgeInformation();



		this.autoUpdateHueBridge = function()
		{
			if(config.autoupdates == true)
			{
				bridge.client.softwareUpdate.check()
				.then(() => {
					return bridge.client.softwareUpdate.get();
				})
				.then(softwareUpdate => {
					return bridge.client.softwareUpdate.install();
				})
				.then(() => {

					if(scope.nodeActive == true)
					{
						setTimeout(function(){ scope.getBridgeInformation(); }, 60000 * 5);
					}
				})
				.catch(error => {

					if(scope.nodeActive == true)
					{
						setTimeout(function(){ scope.autoUpdateHueBridge(); }, 60000 * 180);
					}
				});
			}
		}

		this.autoUpdateHueBridge();



		if(!config.skipglobalevents)
		{
			bridge.events.on('globalDeviceUpdates', function(message)
			{
				if(scope.deviceUpdates == false) { return; }

				let type = message.type;
				let payload = message.payload;
				var detType = type;


				var message = {};
				message.updated = {};


				if(type == "light")
				{
					let hueLight = new HueLightMessage(payload, {colornamer: true});
					message.updated = hueLight.msg;
				}
				else if(type == "group")
				{
					let hueGroup = new HueGroupMessage(payload, {colornamer: true});
					message.updated = hueGroup.msg;
				}
				else if(type == "rule")
				{
					let hueRules = new HueRulesMessage(payload);
					message.updated = hueRules.msg;
				}
				else if(type == "sensor")
				{

					if(payload.type == "ZLLPresence")
					{
						let hueMotion = new HueMotionMessage(payload);
						message.updated = hueMotion.msg;

						detType = "motion";
					}
					else if(payload.type == "ZLLLightLevel")
					{
						let hueBrightness = new HueBrightnessMessage(payload);
						message.updated = hueBrightness.msg;

						detType = "brightness";
					}
					else if(payload.type == "ZLLTemperature")
					{
						let hueTemperature = new HueTemperatureMessage(payload);
						message.updated = hueTemperature.msg;

						detType = "temperature";
					}
					else if(payload.type == "ZLLSwitch")
					{
						let hueSwitch = new HueSwitchMessage(payload);
						message.updated = hueSwitch.msg;

						detType = "switch";
					}
					else if(payload.type == "ZGPSwitch")
					{
						let hueTap = new HueTapMessage(sensor);
						message.updated = hueTap.msg;

						detType = "tap";
					}
				}


				message.updated.type = detType;


				message.info = scope.bridgeInformation;


				scope.send(message);
			});
		}



		this.on('input', function(msg, send, done)
		{

			send = send || function() { scope.send.apply(scope,arguments); }

			var commandSent = false;


			if(typeof msg.payload.touchLink != 'undefined')
			{
				scope.status({fill: "grey", shape: "dot", text: "hue-bridge.node.starting-tl" });
				bridge.client.bridge.touchlink()
				.then(() => {
					scope.status({fill: "blue", shape: "ring", text: "hue-bridge.node.started-tl" });
					if(done) { done(); }
					setTimeout(function(){ scope.getBridgeInformation(); }, 30000);
				})
				.catch(error => {
					scope.error(error);
					if(done) { done(error); }
					setTimeout(function(){ scope.getBridgeInformation(); }, 2000);
