function loadProject(name) {
    let fullPath = fspath.resolve(fspath.join(projectsDir,name));
    var projectPath = name;
    if (projectPath.indexOf(fspath.sep) === -1) {
        projectPath = fullPath;
    } else {

        let relativePath = fspath.relative(projectsDir,fullPath);
        if (/^\.\./.test(relativePath)) {
            throw new Error("Invalid project name")
        }
    }
    return Projects.load(projectPath).then(function(project) {
        activeProject = project;
        flowsFullPath = project.getFlowFile();
        flowsFileBackup = project.getFlowFileBackup();
        credentialsFile = project.getCredentialsFile();
        credentialsFileBackup = project.getCredentialsFileBackup();
        return project;
    })
}

function uploadFile(ev) {
        var form, data, dialog, filename;
        ev.preventDefault();
        form = $("#upload-form");
        filename = form.find('input[name="file"]').val();
        console.log("Filename: "+filename);
        if (filename === "") {
            alert("No file selected");
            return;
        }
        form.find('input[name="ajax"]').val("1");
        data = new FormData(form[0]);
        $("#upload-form .submit").prop("disabled", true);
        dialog = $('#dialog-box')
        dialog.find(".modal-body").html('<p>Uploading ' +
                                        encodeURIComponent(filename) +
                                        '</p><div class="error"></div>');
        showDialog();
        $.ajax({
            url: form.attr("action"),
            data: data,
            type: "POST",
            enctype: 'multipart/form-data',
            processData: false,
            contentType: false,
            timeout: 600000,
            cache: false
        }).done(function (data) {
            var err, htm;

            $("#btnSubmit").prop("disabled", false);
            if(data.error) {
                err = dialog.find('.modal-body .error');
                err.text(data.error);
                return;
            }
            dialog.find(".modal-body").html('<p>Finished uploading ' +
                                            encodeURIComponent(filename) +
                                            '<span class="bool-yes ">&check;</span>');
            if(data.upload_url) {
                $('#upload-form').attr('action', data.upload_url);
            }
            if(data.csrf_token) {
                $('#upload-form input[name="csrf_token"]').val(data.csrf);
            }
            if(data.file_html){
                $('#'+data.name).remove();
                htm = $(data.file_html);
                htm.insertBefore('#media-files .error-row');
                htm.find('.delete-file').click(deleteFile);
                htm.find('.btn-index').click(indexFile);
                window.setTimeout(closeDialog, 500);
            }
        }).fail(function (e) {
            var err = dialog.find('.modal-body .error');
            if (e.responseJSON) {
                err.text(e.responseJSON.error);
            }
            else if (e.statusText) {
                err.text(e.status + ' ' + e.statusText);
            } else if (e.responseText) {
                err.text(e.responseText);
            } else {
                err.text(JSON.stringify(e));
            }
            console.error(e);
        }).always(function() {
            $("#upload-form .submit").prop("disabled", false);
        });
        return false;
    }

function shave(target, maxHeight) {
  var opts = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : {};
  if (!maxHeight) throw Error('maxHeight is required');
  var els = typeof target === 'string' ? document.querySelectorAll(target) : target;
  if (!els) return;
  var character = opts.character || '…';
  var classname = opts.classname || 'js-shave';
  var spaces = typeof opts.spaces === 'boolean' ? opts.spaces : true;
  var charHtml = "<span class=\"js-shave-char\">".concat(character, "</span>");
  if (!('length' in els)) els = [els];

  for (var i = 0; i < els.length; i += 1) {
    var el = els[i];
    var styles = el.style;
    var span = el.querySelector(".".concat(classname));
    var textProp = el.textContent === undefined ? 'innerText' : 'textContent'; 

    if (span) {

      el.removeChild(el.querySelector('.js-shave-char'));
      el[textProp] = el[textProp]; 

    }

    var fullText = el[textProp];
    var words = spaces ? fullText.split(' ') : fullText; 

    if (words.length < 2) continue; 

    var heightStyle = styles.height;
    styles.height = 'auto';
    var maxHeightStyle = styles.maxHeight;
    styles.maxHeight = 'none'; 

    if (el.offsetHeight <= maxHeight) {
      styles.height = heightStyle;
      styles.maxHeight = maxHeightStyle;
      continue;
    } 


    var max = words.length - 1;
    var min = 0;
    var pivot = void 0;

    while (min < max) {
      pivot = min + max + 1 >> 1; 

      el[textProp] = spaces ? words.slice(0, pivot).join(' ') : words.slice(0, pivot);
      el.insertAdjacentHTML('beforeend', charHtml);
      if (el.offsetHeight > maxHeight) max = spaces ? pivot - 1 : pivot - 2;else min = pivot;
    }

    el[textProp] = spaces ? words.slice(0, max).join(' ') : words.slice(0, max);
    el.insertAdjacentHTML('beforeend', charHtml);
    var diff = spaces ? " ".concat(words.slice(max).join(' ')) : words.slice(max);
    var shavedText = document.createTextNode(diff);
    var elWithShavedText = document.createElement('span');
    elWithShavedText.classList.add(classname);
    elWithShavedText.style.display = 'none';
    elWithShavedText.appendChild(shavedText);
    el.insertAdjacentElement('beforeend', elWithShavedText);
    styles.height = heightStyle;
    styles.maxHeight = maxHeightStyle;
  }
}

function detailedDataTableMapper(entry) {
  const project = Projects.findOne({ _id: entry.projectId })
  const mapping = [project ? project.name : '',
    dayjs.utc(entry.date).format(getGlobalSetting('dateformat')),
    entry.task.replace(/^=/, '='),
    projectUsers.findOne() ? projectUsers.findOne().users.find((elem) => elem._id === entry.userId)?.profile?.name : '']
  if (getGlobalSetting('showCustomFieldsInDetails')) {
    if (CustomFields.find({ classname: 'time_entry' }).count() > 0) {
      for (const customfield of CustomFields.find({ classname: 'time_entry' }).fetch()) {
        mapping.push(entry[customfield[customFieldType]])
      }
    }
    if (CustomFields.find({ classname: 'project' }).count() > 0) {
      for (const customfield of CustomFields.find({ classname: 'project' }).fetch()) {
        mapping.push(project[customfield[customFieldType]])
      }
    }
  }
  if (getGlobalSetting('showCustomerInDetails')) {
    mapping.push(project ? project.customer : '')
  }
  if (getGlobalSetting('useState')) {
    mapping.push(entry.state)
  }
  mapping.push(Number(timeInUserUnit(entry.hours)))
  mapping.push(entry._id)
  return mapping
}

