        gui += '<li class="instance">';
        if (instance.label != '') {
            if (isCurrent) {
                gui += '<h4 title="' + _.escape(instance.label) + '"><span class="pipeline_run_label">Instance: ' + _.escape(instance.label) + '</span></h4>';
            }
